// Inventory Service: manages stock across warehouses with atomic reservations
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<InventoryDbContext>(opt =>
    opt.UseSqlServer(builder.Configuration.GetConnectionString("InventoryDb"))
);
builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);

var app = builder.Build();

app.MapPost("/inventory/reserve", async (ReserveStockRequest req, InventoryDbContext db) => {
    // Atomic stock reservation using pessimistic locking
    var stock = await db.InventoryItems
        .FirstOrDefaultAsync(s => s.ProductId == req.ProductId && s.WarehouseId == req.WarehouseId);
    if (stock == null || stock.AvailableQuantity < req.Quantity)
        return Results.Conflict("Insufficient stock");

    stock.AvailableQuantity -= req.Quantity;
    stock.ReservedQuantity += req.Quantity;
    await db.SaveChangesAsync();

    // Set TTL for auto-release if order is not completed
    await cache.SetStringAsync(
        $"reservation:{req.OrderId}",
        req.ProductId,
        new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15) }
    );

    return Results.Ok(new { stock.AvailableQuantity });
})
.WithName("ReserveStock");

app.MapPost("/inventory/commit", async (CommitStockRequest req, InventoryDbContext db) => {
    var stock = await db.InventoryItems
        .FirstOrDefaultAsync(s => s.ProductId == req.ProductId);
    if (stock != null)
    {
        stock.ReservedQuantity -= req.Quantity;
        await db.SaveChangesAsync();
    }
    await cache.RemoveAsync($"reservation:{req.OrderId}");
    return Results.Ok();
})
.WithName("CommitStock");

app.MapGet("/health", () => Results.Ok());
app.Run();
